"<script>"
"var selectedNetwork=null,selectedBleDevice=null,selectedAttack='deauth',selectedModule='wifi',customTime=2,dosMethod=1,handshakeMethod=1,networksCache=[],bleScanDevices=[];"
"function byId(id){return document.getElementById(id)}function toast(msg,bad){var t=document.createElement('div');t.className=bad?'bad':'';t.textContent=msg;byId('toast').appendChild(t);setTimeout(function(){t.remove()},3200)}"
"function addLog(msg,type){var d=byId('logArea'),e=document.createElement('div');e.className=type||'';e.textContent='['+new Date().toLocaleTimeString()+'] '+msg;d.appendChild(e);d.scrollTop=d.scrollHeight}"
"function api(url,opts){return fetch(url,opts||{}).then(function(r){if(!r.ok){throw new Error(r.status)}return r.json().catch(function(){return {success:true}})})}"
"function confirmRun(msg,fn){if(confirm(msg)){fn()}}function needTarget(){if(!selectedNetwork){toast('Select a target network first',true);addLog('No target selected','warning');return false}return true}"
"function toggleTheme(){var h=document.documentElement,t=h.getAttribute('data-theme')==='dark'?'light':'dark';h.setAttribute('data-theme',t);localStorage.setItem('theme',t)}function logout(){location.href='/logout'}"
"function selectModule(m){selectedModule=m;document.querySelectorAll('.module').forEach(function(x){x.classList.toggle('active',x.dataset.module===m)});['wifi','ble','mesh'].forEach(function(k){byId(k+'-attacks').style.display=k===m?'grid':'none';var panel=byId(k+'-target-panel');if(panel){panel.style.display=k===m?'block':'none'}});addLog('Module selected: '+m.toUpperCase())}"
"function selectAttack(a){selectedAttack=a;document.querySelectorAll('[data-attack]').forEach(function(x){x.classList.toggle('selected',x.dataset.attack===a)});document.querySelectorAll('.attack-panel').forEach(function(x){x.classList.remove('active')});byId(a+'Panel').classList.add('active');addLog('Attack selected: '+a.toUpperCase())}"
"function signalPct(r){return Math.max(0,Math.min(100,2*(Number(r)+100)))}function esc(s){return String(s||'').replace(/[&<>]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;'}[c]})}"
"function renderNetworks(){var q=byId('networkFilter').value.toLowerCase(),tbody=byId('networksTable');tbody.innerHTML='';var list=networksCache.filter(function(n){return (n.ssid||'Hidden').toLowerCase().indexOf(q)>-1||n.bssid.toLowerCase().indexOf(q)>-1});byId('statNetworks').textContent=list.length;if(!list.length){tbody.innerHTML='<tr><td colspan=7 class=empty>No networks found</td></tr>';return}list.forEach(function(n){var tr=document.createElement('tr'),p=signalPct(n.rssi),secure=n.authmode!=='Open';if(selectedNetwork&&selectedNetwork.bssid===n.bssid){tr.className='row-selected'}tr.innerHTML='<td><b>'+esc(n.ssid||'Hidden')+'</b></td><td>'+esc(n.bssid)+'</td><td>'+n.channel+'</td><td>'+n.rssi+' dBm</td><td><div class=signal><i style=width:'+p+'%></i></div></td><td><span class=\"pill '+(secure?'secure':'open')+'\">'+esc(n.authmode)+'</span></td><td><button class=\"btn soft\">Select</button></td>';tr.querySelector('button').onclick=function(){selectNetwork(n)};tbody.appendChild(tr)})}"
"function selectNetwork(n){selectedNetwork=n;byId('selectedName').textContent=n.ssid||'Hidden';byId('selectedMeta').textContent=n.bssid+' | CH '+n.channel+' | '+n.rssi+' dBm';byId('statTarget').textContent=n.ssid||'Hidden';renderNetworks();addLog('Target selected: '+(n.ssid||'Hidden'),'success')}"
"function clearTarget(){selectedNetwork=null;byId('selectedName').textContent='No network selected';byId('selectedMeta').textContent='Choose a target from scan results';byId('statTarget').textContent='None';renderNetworks()}"
"function renderSelectedBleDevice(){var html='No BLE device selected.';var details='No BLE device selected.'; if(selectedBleDevice){details='<b>'+esc(selectedBleDevice.name||'<unknown>')+'</b> | '+esc(selectedBleDevice.addr||'unknown')+' | RSSI: '+esc(selectedBleDevice.rssi||0);} var container=byId('bleSelectedDevice'); if(container){container.innerHTML=details;} var panel=byId('bleSelectedDevicePanel'); if(panel){panel.innerHTML=details;} }"
"function scanNetworks(){var b=byId('scanBtn');b.disabled=true;b.textContent='Scanning';addLog('Scanning for networks...');api('/api/scan').then(function(data){networksCache=data;renderNetworks();toast('Found '+data.length+' networks');addLog('Found '+data.length+' networks','success')}).catch(function(){toast('Scan failed',true);addLog('Scan failed','warning')}).finally(function(){b.disabled=false;b.textContent='Scan'})}"
"function startDeauthAttack(){if(!needTarget())return;customTime=parseInt(byId('customTimeInput').value)||2;api('/api/attack',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({bssid:selectedNetwork.bssid,channel:selectedNetwork.channel,minutes:customTime})}).then(function(){byId('stateBadge').textContent='Running';byId('stateBadge').className='badge warn';byId('statusMsg').textContent='Deauth running: '+(selectedNetwork.ssid||selectedNetwork.bssid);toast('Deauth started');addLog('Deauth started for '+customTime+' minutes','attack')}).catch(function(){toast('Deauth failed',true)})}"
"function stopDeauthAttack(){api('/api/stop',{method:'POST'}).then(function(){byId('statusMsg').textContent='Deauth stopped';byId('stateBadge').textContent='Ready';byId('stateBadge').className='badge ok';addLog('Deauth stopped','warning')})}"
"function startBeaconSpam(){api('/api/beacon/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode:parseInt(byId('beaconMode').value),count:parseInt(byId('beaconCount').value)})}).then(function(){toast('Beacon spam started');addLog('Beacon spam started','attack')})}function stopBeaconSpam(){api('/api/beacon/stop',{method:'POST'}).then(function(){addLog('Beacon spam stopped','warning')})}"
"function startDosAttack(){if(!needTarget())return;api('/api/dos/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({bssid:selectedNetwork.bssid,ssid:selectedNetwork.ssid,channel:selectedNetwork.channel,method:dosMethod})}).then(function(){toast('DoS started');addLog('DoS started','attack')})}"
"function startHandshakeCapture(){if(!needTarget())return;api('/api/handshake/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({bssid:selectedNetwork.bssid,ssid:selectedNetwork.ssid,channel:selectedNetwork.channel,method:handshakeMethod})}).then(function(){toast('Handshake capture started');addLog('Handshake capture started','attack')})}"
"function startPmkidAttack(){if(!needTarget())return;api('/api/pmkid/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({bssid:selectedNetwork.bssid,ssid:selectedNetwork.ssid,channel:selectedNetwork.channel})}).then(function(){toast('PMKID started');addLog('PMKID started','attack')})}"
"function startProbeSniffer(){api('/api/probe/start',{method:'POST'}).then(function(){toast('Probe sniffer started');addLog('Probe sniffer started','attack')})}"
"function startEvilTwin(){if(!needTarget())return;api('/api/eviltwin/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({bssid:selectedNetwork.bssid,ssid:selectedNetwork.ssid,channel:selectedNetwork.channel})}).then(function(){toast('Evil Twin started');addLog('Evil Twin started','attack')})}"
"function renderBleScanResults(devices){bleScanDevices=devices||[];var container=byId('bleScanResults');var panel=byId('bleScanResultsPanel');if(!devices||!devices.length){if(container){container.textContent='No BLE devices found.';}if(panel){panel.textContent='No BLE devices found.';}return;} if(container){container.innerHTML='';} if(panel){panel.innerHTML='';} devices.forEach(function(d,i){var name=d.name||'<unknown>'; function makeLine(){var line=document.createElement('div');line.style.marginBottom='6px';line.style.cursor='pointer';line.style.padding='6px';line.style.border='1px solid rgba(255,255,255,.08)';line.style.borderRadius='6px';line.innerHTML='<b>'+esc(name)+'</b> | '+esc(d.addr||'unknown')+' | RSSI: '+esc(d.rssi||0);line.onclick=function(){selectBleDevice(i)};return line;} if(container){container.appendChild(makeLine());} if(panel){panel.appendChild(makeLine());}})}function selectBleDevice(index){var dev=bleScanDevices[index];if(!dev)return;selectedBleDevice=dev;var name=dev.name||'';var addr=dev.addr||'';if(name){byId('bleSpoofName').value=name;}if(addr){if(byId('bleConnectAddr'))byId('bleConnectAddr').value=addr;if(byId('bleL2capAddr'))byId('bleL2capAddr').value=addr;if(byId('bleGattAddr'))byId('bleGattAddr').value=addr;}renderSelectedBleDevice();toast('Selected BLE device '+(name||addr));addLog('Selected BLE device '+(name||addr),'success')}function startBleScan(){var btn=byId('startBleScan');if(btn)btn.disabled=true;api('/api/ble/scan').then(function(data){renderBleScanResults(data);renderSelectedBleDevice();toast('BLE scan complete: '+(data.length||0)+' devices');addLog('BLE scan returned '+(data.length||0)+' devices','success')}).catch(function(){toast('BLE scan failed',true);addLog('BLE scan failed','warning')}).finally(function(){if(btn){btn.disabled=false}})}"
"function startBleSpoof(){var name=byId('bleSpoofName')?byId('bleSpoofName').value:null;api('/api/ble/spoof/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:name})}).then(function(){toast('BLE spoof started');addLog('BLE spoof started','attack')}).catch(function(){toast('BLE spoof failed',true)})}"
"function stopBleSpoof(){api('/api/ble/spoof/stop',{method:'POST'}).then(function(){toast('BLE spoof stopped');addLog('BLE spoof stopped','warning')}).catch(function(){toast('BLE spoof stop failed',true)})}"
"function startBleConnect(){var addr=byId('bleConnectAddr')?byId('bleConnectAddr').value:null;if(!addr){toast('Enter target BLE address first',true);return;}api('/api/ble/connect/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({addr:addr})}).then(function(){toast('BLE connect flood started');addLog('BLE connect flood started','attack')}).catch(function(){toast('BLE connect failed',true)})}"
"function stopBleConnect(){api('/api/ble/connect/stop',{method:'POST'}).then(function(){toast('BLE connect stopped');addLog('BLE connect stopped','warning')}).catch(function(){toast('BLE connect stop failed',true)})}"
"function startBleL2cap(){var addr=byId('bleL2capAddr')?byId('bleL2capAddr').value:null;if(!addr){toast('Enter target BLE address first',true);return;}api('/api/ble/l2cap/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({addr:addr})}).then(function(){toast('BLE L2CAP flood started');addLog('BLE l2cap started','attack')}).catch(function(){toast('BLE l2cap failed',true)})}"
"function stopBleL2cap(){api('/api/ble/l2cap/stop',{method:'POST'}).then(function(){toast('BLE l2cap stopped');addLog('BLE l2cap stopped','warning')}).catch(function(){toast('BLE l2cap stop failed',true)})}"
"function startBleGatt(){var addr=byId('bleGattAddr')?byId('bleGattAddr').value:null;if(!addr){toast('Enter target BLE address first',true);return;}api('/api/ble/gatt/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({addr:addr})}).then(function(){toast('BLE GATT probe started');addLog('BLE gatt started','attack')}).catch(function(){toast('BLE gatt failed',true)})}"
"function stopBleGatt(){api('/api/ble/gatt/stop',{method:'POST'}).then(function(){toast('BLE gatt stopped');addLog('BLE gatt stopped','warning')}).catch(function(){toast('BLE gatt stop failed',true)})}"
"function startBleSpam(){var type=parseInt(byId('bleDeviceType').value)||25;var delay=parseInt(byId('bleDelayInput').value)||0;api('/api/ble/spam/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({device_type:type,delay_ms:delay})}).then(function(){byId('bleStatusMsg').textContent='BLE spam active';byId('bleState').textContent='Running';toast('BLE spam started');addLog('BLE spam started, type:'+type+', delay:'+delay+'ms','attack')}).catch(function(){toast('BLE spam failed',true);addLog('BLE spam failed','warning')})}"
"function stopBleSpam(){api('/api/ble/spam/stop',{method:'POST'}).then(function(){byId('bleStatusMsg').textContent='BLE spam stopped';byId('bleState').textContent='Stopped';addLog('BLE spam stopped','warning')}).catch(function(){toast('BLE stop failed',true);addLog('BLE stop failed','warning')})}"
"function stopAllAttacks(){api('/api/stop/all',{method:'POST'}).then(function(){byId('stateBadge').textContent='Ready';byId('stateBadge').className='badge ok';byId('statusMsg').textContent='All attacks stopped';byId('timerDisplay').textContent='Idle';byId('statTimer').textContent='Idle';toast('All attacks stopped');addLog('All attacks stopped','warning')})}"
"function updateStatus(){api('/api/status').then(function(d){if(d.ble_running){byId('stateBadge').textContent='BLE Running';byId('stateBadge').className='badge warn';byId('statusMsg').textContent='BLE spam active';if(d.remaining){var m=Math.floor(d.remaining/60),s=d.remaining%60,txt=m+'m '+s+'s';byId('timerDisplay').textContent=txt;byId('statTimer').textContent=txt}}else if(d.attacking){byId('stateBadge').textContent='Running';byId('stateBadge').className='badge warn';byId('statusMsg').textContent='Active target: '+(d.target||'unknown');if(d.remaining){var m=Math.floor(d.remaining/60),s=d.remaining%60,txt=m+'m '+s+'s';byId('timerDisplay').textContent=txt;byId('statTimer').textContent=txt}}else{byId('stateBadge').textContent='Ready';byId('stateBadge').className='badge ok';byId('statusMsg').textContent='Ready';byId('timerDisplay').textContent='Idle';byId('statTimer').textContent='Idle'}}).catch(function(){})}"
"function updateDetector(){api('/api/detector').then(function(d){byId('statDetector').textContent=d.tracked_bssids||0;if(d.alerts&&d.alerts.length){byId('alerts').innerHTML=d.alerts.map(function(a){return '<b>Alert</b> '+esc(a.bssid)+' | Frames: '+a.count}).join('<br>');addLog('Detector alert received','warning')}else{byId('alerts').textContent='No deauth alerts detected'}}).catch(function(){})}"
"function bind(){var saved=localStorage.getItem('theme')||'dark';document.documentElement.setAttribute('data-theme',saved);byId('themeBtn').onclick=toggleTheme;byId('logoutBtn').onclick=logout;byId('scanBtn').onclick=scanNetworks;byId('clearTargetBtn').onclick=clearTarget;byId('networkFilter').oninput=renderNetworks;byId('stopAllBtn').onclick=function(){confirmRun('Stop all running actions?',stopAllAttacks)};document.querySelectorAll('[data-module]').forEach(function(x){x.onclick=function(){selectModule(x.dataset.module)}});document.querySelectorAll('[data-attack]').forEach(function(x){x.onclick=function(){selectAttack(x.dataset.attack)}});document.querySelectorAll('[data-dos]').forEach(function(x){x.onclick=function(){dosMethod=parseInt(x.dataset.dos);document.querySelectorAll('[data-dos]').forEach(function(y){y.classList.remove('active')});x.classList.add('active')}});document.querySelectorAll('[data-handshake]').forEach(function(x){x.onclick=function(){handshakeMethod=parseInt(x.dataset.handshake);document.querySelectorAll('[data-handshake]').forEach(function(y){y.classList.remove('active')});x.classList.add('active')}});byId('startDeauth').onclick=function(){confirmRun('Start deauth on selected target?',startDeauthAttack)};byId('stopDeauth').onclick=stopDeauthAttack;byId('startBeacon').onclick=function(){confirmRun('Start beacon spam?',startBeaconSpam)};byId('stopBeacon').onclick=stopBeaconSpam;byId('startDos').onclick=function(){confirmRun('Start DoS on selected target?',startDosAttack)};byId('startHandshake').onclick=function(){confirmRun('Start handshake capture?',startHandshakeCapture)};byId('startPmkid').onclick=function(){confirmRun('Start PMKID capture?',startPmkidAttack)};byId('startProbe').onclick=function(){confirmRun('Start probe sniffer?',startProbeSniffer)};byId('startEvilTwin').onclick=function(){confirmRun('Start Evil Twin on selected target?',startEvilTwin)};var x=byId('startBleScan');if(x)x.onclick=function(){confirmRun('Start BLE scan?',startBleScan)};x=byId('startBleSpam');if(x)x.onclick=function(){confirmRun('Start BLE spam?',startBleSpam)};x=byId('stopBleSpam');if(x)x.onclick=stopBleSpam;x=byId('startBleSpoof');if(x)x.onclick=function(){confirmRun('Start BLE spoof?',startBleSpoof)};x=byId('stopBleSpoof');if(x)x.onclick=stopBleSpoof;x=byId('startBleConnect');if(x)x.onclick=function(){confirmRun('Start connect flood?',startBleConnect)};x=byId('stopBleConnect');if(x)x.onclick=stopBleConnect;x=byId('startBleL2cap');if(x)x.onclick=function(){confirmRun('Start L2CAP flood?',startBleL2cap)};x=byId('stopBleL2cap');if(x)x.onclick=stopBleL2cap;x=byId('startBleGatt');if(x)x.onclick=function(){confirmRun('Start GATT probe?',startBleGatt)};x=byId('stopBleGatt');if(x)x.onclick=stopBleGatt;addLog('Dashboard ready','success');scanNetworks();setInterval(updateStatus,2000);setInterval(updateDetector,3000)}"
"document.addEventListener('DOMContentLoaded',bind);"
"</script></body></html>";

#endif
